def test_expand_tabs_style():
    text = Text("Hello\tWorld")
    text.stylize("red", 0, 6)
    text.expand_tabs(tab_size=8)

    # The tab was at index 5. Expanded to 3 spaces (indices 5, 6, 7).
    # We expect indices 0-7 to be red.
    # We can check this by seeing if the spans cover 0-8 with red.

    red_ranges = []
    for span in text._spans:
        if span.style == "red":
            red_ranges.append((span.start, span.end))

    # Merge ranges
    if not red_ranges:
        raise AssertionError("No red spans found")

    red_ranges.sort()
    merged = [red_ranges[0]]
    for current in red_ranges[1:]:
        prev = merged[-1]
        if current[0] <= prev[1]:
            merged[-1] = (prev[0], max(prev[1], current[1]))
        else:
            merged.append(current)

    assert merged == [(0, 8)], f"Expected red range (0, 8), got {merged}"

if __name__ == "__main__":
    try:
        test_expand_tabs_style()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
